def category_breakdown(entries, month):
    """Totals per category for one month, given as "YYYY-MM".

    Returns a list of (category, total) tuples sorted by total ascending, so
    the largest expense comes first, with ties broken by category name.
    Categories whose total is exactly zero are left out. Entries from other
    months are ignored. Same single-currency rule as monthly_totals.
    """
    if not entries:
        return []

    currency = entries[0].currency
    for entry in entries:
        if entry.currency != currency:
            raise ValueError("All entries must share the same currency")

    totals_per_category = {}
    for entry in entries:
        entry_month = f"{entry.day.year}-{entry.day.month:02d}"
        if entry_month == month:
            totals_per_category[entry.category] = totals_per_category.get(entry.category, Decimal("0.00")) + entry.amount

    result = []
    for category, total in totals_per_category.items():
        if total != Decimal("0.00"):
            result.append((category, total))

    # Sort by total ascending, then category name
    result.sort(key=lambda x: (x[1], x[0]))
    return result

